SELECT hours,COUNT(*) move_events FROM (SELECT 1 hours UNION ALL SELECT 24 UNION ALL SELECT 168) windows JOIN (SELECT x.src,x.dst,x.dst_rev,x.hash,MIN(ABS(TIMESTAMPDIFF(SECOND,p.e,x.at))) distance FROM edges x JOIN presence p ON p.hash=x.hash AND p.page_id=x.src AND p.s<x.at GROUP BY x.src,x.dst,x.dst_rev,x.hash) e ON e.distance<=hours*3600 GROUP BY hours,e.src,e.dst,e.dst_rev HAVING COUNT(*)>=5;
